window.TEACH_SLIDES['7-22'] = [{"k": "title", "html": "<p class=\"ts-kicker\">ថ្នាក់ទី ៧ · មេរៀនទី ២២</p><h1>ក្រាបផ្លិត និងក្រាបខ្សែ</h1><div class=\"ts-obj\"><h3>គោលបំណង</h3><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">1.</span><div>បង្កើតតារាងបំណែងចែកទិន្នន័យ</div></li><li class=\"lab\"><span class=\"lb\">2.</span><div>បកស្រាយទិន្នន័យតាមក្រាបផ្លិតនិងក្រាបខ្សែ ។</div></li></ul></div>", "c": "cover"}, {"k": "title", "html": "<h1>1. ក្រាបផ្លិត</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ឧទាហរណ៍ 1 <span class=\"ts-pg\">(១/៣)</span></h2><p>ពូចាន់ជាម្ចាស់កសិដ្ឋានចិញ្ចឹមសត្វមួយកន្លែង ។ ក្នុងកសិដ្ឋាននោះមានមាន់ចំនួន 60 ក្បាល ទាចំនួន 40 ក្បាល និងក្ងានចំនួន 20 ក្បាល ។ <br> ដើម្បីងាយស្រួលក្នុងការសង្កេតចំនួនសត្វតាមប្រភេទនីមួយៗធៀបនឹងចំនួនសត្វទាំងអស់ គេត្រូវតាងចំនួនសត្វទាំងអស់ដោយរូបថាសមួយ រួចគេរកផលធៀបរវាងចំនួនសត្វតាមប្រភេទនិងចំនួនសត្វទាំងអស់ ។ <br> ចំនួនសត្វទាំងអស់មាន <br> 60 ក្បាល + 40 ក្បាល + 20 ក្បាល</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ឧទាហរណ៍ 1 <span class=\"ts-pg\">(២/៣)</span></h2><ul class=\"ts-bullets\"><li>ចំនួនមាន់មាន \\(\\frac{60}{120} = \\frac{1}{2}\\) នៃចំនួនសត្វទាំងអស់ <br> មានន័យថា 1 ភាគ 2 នៃថាស ។ <br> \\(\\frac{1}{2}\\) នៃថាស បើគិតជាមុំត្រូវនឹង \\(\\frac{1}{2} \\times 360^\\circ = 180^\\circ\\) ។</li><li>ចំនួនទាមាន \\(\\frac{40}{120} = \\frac{1}{3}\\) នៃចំនួនសត្វទាំងអស់ <br> មានន័យថា 1 ភាគ 3 នៃថាស ។ <br> \\(\\frac{1}{3}\\) នៃថាស បើគិតជាមុំត្រូវនឹង \\(\\frac{1}{3} \\times 360^\\circ = 120^\\circ\\) ។</li><li>ចំនួនក្ងានមាន \\(\\frac{20}{120} = \\frac{1}{6}\\) នៃចំនួនសត្វទាំងអស់ <br> មានន័យថា 1 ភាគ 6 នៃថាស ។ <br> \\(\\frac{1}{6}\\) នៃថាស បើគិតជាមុំត្រូវនឹង \\(\\frac{1}{6} \\times 360^\\circ = 60^\\circ\\) ។</li></ul><p>គេបានតារាងបំណែងចែកទិន្នន័យ</p><table class=\"ts-table\"><tr><td>សត្វ</td><td>ចំនួនសត្វ</td><td>មុំចម្រៀកថាស</td></tr><tr><td>មាន់</td><td>60</td><td>\\(180^\\circ\\)</td></tr><tr><td>ទា</td><td>40</td><td>\\(120^\\circ\\)</td></tr><tr><td>ក្ងាន</td><td>20</td><td>\\(60^\\circ\\)</td></tr></table><p>ចំនួនសត្វតាមផ្នែកនីមួយៗដែលគេបានតាងនោះមានរាងជាផ្លិតទើបគេហៅថា ក្រាបផ្លិត ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ឧទាហរណ៍ 1 <span class=\"ts-pg\">(៣/៣)</span></h2><p><b>ក្រាបផ្លិត</b> ជាក្រាបដែលមានរាងជាថាសរង្វង់តាងឱ្យទិន្នន័យស្ថិតិដើម្បីងាយស្រួលក្នុងការបកស្រាយទិន្នន័យ ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ឧទាហរណ៍ 2 <span class=\"ts-pg\">(១/៣)</span></h2><p>គេបានធ្វើការកត់ត្រា ការលក់សាំង(គិតជាពាន់លីត្រ) ក្នុងស្ថានីយលក់សាំងចំនួន 4 កន្លែងដែលគេតាងដោយ A, B, C និង D នៅសប្តាហ៍ទី 1 នៃខែមករា ។</p><table class=\"ts-table\"><tr><td>ស្ថានីយសាំង</td><td>A</td><td>B</td><td>C</td><td>D</td></tr><tr><td>សាំង(ពាន់លីត្រ)</td><td>90</td><td>140</td><td>30</td><td>20</td></tr></table>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ឧទាហរណ៍ 2 <span class=\"ts-pg\">(២/៣)</span></h2><p>គេចង់បង្ហាញទិន្នន័យខាងលើជាក្រាបផ្លិត <br> ដំបូងគេត្រូវរកចំនួនសាំងលក់សរុបទាំង 4 ស្ថានីយ <br> 90 ពាន់លីត្រ + 140 ពាន់លីត្រ + 30 ពាន់លីត្រ + 20 ពាន់លីត្រ = 280 ពាន់លីត្រ ។ <br> ចំនួនសាំងលក់សរុបនេះ នឹងត្រូវយកមកតាងជារង្វង់ ឬថាសមួយ ។ ដូច្នេះ 280 ពាន់លីត្រត្រូវនឹងមុំផ្ចិតរង្វង់ \\(360^\\circ\\) ។ <br> គេបាន <br> 90 ពាន់លីត្រ ត្រូវនឹងមុំ \\(\\frac{360^\\circ}{280} \\times 90 = 115.7^\\circ\\) <br> 140 ពាន់លីត្រ ត្រូវនឹងមុំ \\(\\frac{360^\\circ}{280} \\times 140 = 180^\\circ\\) <br> 30 ពាន់លីត្រ ត្រូវនឹងមុំ \\(\\frac{360^\\circ}{280} \\times 30 = 38.6^\\circ\\) <br> 20 ពាន់លីត្រ ត្រូវនឹងមុំ \\(\\frac{360^\\circ}{280} \\times 20 = 25.7^\\circ\\) <br> តាមរង្វាស់មុំខាងលើ គេអាចសង់ក្រាបផ្លិតបានដោយប្រើរ៉ាបទ័រ ។</p><p>គេបានតារាងបំណែងចែកទិន្នន័យ</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ឧទាហរណ៍ 2 <span class=\"ts-pg\">(៣/៣)</span></h2><table class=\"ts-table\"><tr><td>ស្ថានីយសាំង</td><td>ចំនួនសាំង(ពាន់លីត្រ)</td><td>មុំចម្រៀកថាស</td></tr><tr><td>A</td><td>90</td><td>\\(115.7^\\circ\\)</td></tr><tr><td>B</td><td>140</td><td>\\(180^\\circ\\)</td></tr><tr><td>C</td><td>30</td><td>\\(38.6^\\circ\\)</td></tr><tr><td>D</td><td>20</td><td>\\(25.7^\\circ\\)</td></tr></table>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>លំហាត់គំរូ 1</h2><p>ប្រើប្រាស់ទិន្នន័យក្នុងតារាងខាងក្រោម ដើម្បីសង់ក្រាបផ្លិតដែលបង្ហាញអំពីការចំណាយប្រចាំខែរបស់ក្រុមហ៊ុនមួយ ហើយបកស្រាយទិន្នន័យដែលបង្ហាញនៅក្នុងក្រាបផ្លិតនោះ ។</p><table class=\"ts-table\"><tr><td>ការចំណាយប្រចាំខែ</td><td>ចំនួនទឹកប្រាក់</td></tr><tr><td>កាតទូរស័ព្ទ</td><td>500 000 ៛</td></tr><tr><td>សាំងយានយន្ត</td><td>1 000 000 ៛</td></tr><tr><td>សម្ភារៈការិយាល័យ</td><td>1 200 000 ៛</td></tr><tr><td>អគ្គិសនី</td><td>900 000 ៛</td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ដំណោះស្រាយ</h2><p>សង់ក្រាបផ្លិត</p><p>ផ្អែកលើក្រាបផ្លិត ក្រុមហ៊ុនចំណាយច្រើនជាងគេលើសម្ភារៈការិយាល័យនិងចំណាយតិចជាងគេលើកាតទូរស័ព្ទធៀបនឹងចំណាយសរុប 3 600 000 ៛ ក្នុងមួយខែ ។ <br> ការប្រើប្រាស់ក្រាបផ្លិតមានភាពងាយស្រួលក្នុងការវិភាគទិន្នន័យដែលបានបែងចែកតាមផ្នែកនីមួយៗ ។ ការដឹងពីចំណាយនេះជួយឱ្យក្រុមហ៊ុនអាចធ្វើផែនការចំណាយនៅខែបន្ទាប់ ជាពិសេសក្រុមហ៊ុនក៏អាចព្យាករពីការចំណាយប្រចាំឆ្នាំដើម្បីដាក់បញ្ចូលក្នុងផែនការហិរញ្ញវត្ថុរបស់ខ្លួនផងដែរ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>លំហាត់គំរូ 2</h2><p>ខាងស្តាំនេះជាតារាងទិន្នន័យនៃមធ្យោបាយធ្វើដំណើររបស់និស្សិតនៅសាកលវិទ្យាល័យមួយ ។ តាងទិន្នន័យជាក្រាបផ្លិត ។</p><table class=\"ts-table\"><tr><td>មធ្យោបាយធ្វើដំណើរ</td><td>អត្រាជាភាគរយ</td></tr><tr><td>ឡាន</td><td>10</td></tr><tr><td>ម៉ូតូ</td><td>75</td></tr><tr><td>កង់</td><td>15</td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ដំណោះស្រាយ</h2><p>តាងអត្រា 100% ដោយរូបថាសទាំងមូលឬរង្វង់ <br> គេដឹងថា 100% ត្រូវនឹងមុំផ្ចិត \\(360^\\circ\\) <br> ឡាន 10% នៃថាសត្រូវនឹង \\(\\frac{360^\\circ}{100} \\times 10 = 36^\\circ\\) <br> ម៉ូតូ 75% នៃថាសត្រូវនឹង \\(\\frac{360^\\circ}{100} \\times 75 = 270^\\circ\\) <br> កង់ 15% នៃថាសត្រូវនឹង \\(\\frac{360^\\circ}{100} \\times 15 = 54^\\circ\\)</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ប្រតិបត្តិ 1</h2><p>ក្រាបផ្លិតខាងក្រោម បង្ហាញពីចំណូលប្រចាំខែរបស់ក្រុមហ៊ុនលក់ឧបករណ៍អេឡិចត្រូនិក</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បកស្រាយក្រាបផ្លិតនេះ ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើក្រុមហ៊ុនទទួលបានចំណូលពីការលក់អ្វីខ្លះ? តើព័ត៌មាននេះមានសារៈប្រយោជន៍អ្វីខ្លះសម្រាប់ក្រុមហ៊ុនក្នុងការធ្វើផែនការហិរញ្ញវត្ថុ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ចម្លើយ <span class=\"ts-pg\">(១/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>គណនាចំណូលសរុបប្រចាំខែរបស់ក្រុមហ៊ុន ៖ \\[\\begin{aligned}\n    S &amp;= 6~000~000 + 4~500~000 + 2~000~000 + 3~000~000 \\\\\n      &amp;= 15~500~000\\text{ ៛}\n    \\end{aligned}\\] ផ្អែកលើក្រាបផ្លិត ៖</p><ul class=\"ts-bullets\"><li>ការលក់ទូរទស្សន៍ផ្តល់ចំណូលច្រើនជាងគេ គឺ \\(6~000~000\\text{ ៛}\\) ស្មើនឹង \\(\\frac{6~000~000}{15~500~000} \\times 100\\% \\approx 38.71\\%\\) (ត្រូវនឹងមុំផ្ចិតប្រហែល \\(139.35^\\circ\\))</li></ul><ul class=\"ts-bullets\"><li>ការលក់បាសនិងម៉ាញ៉េផ្តល់ចំណូល \\(4~500~000\\text{ ៛}\\) ស្មើនឹង \\(\\frac{4~500~000}{15~500~000} \\times 100\\% \\approx 29.03\\%\\) (ត្រូវនឹងមុំផ្ចិតប្រហែល \\(104.52^\\circ\\))</li></ul><ul class=\"ts-bullets\"><li>សេវាជួសជុលផ្តល់ចំណូល \\(3~000~000\\text{ ៛}\\) ស្មើនឹង \\(\\frac{3~000~000}{15~500~000} \\times 100\\% \\approx 19.35\\%\\) (ត្រូវនឹងមុំផ្ចិតប្រហែល \\(69.68^\\circ\\))</li></ul><ul class=\"ts-bullets\"><li>ការលក់ម៉ាស៊ីនព្រីនផ្តល់ចំណូលតិចជាងគេ គឺ \\(2~000~000\\text{ ៛}\\) ស្មើនឹង \\(\\frac{2~000~000}{15~500~000} \\times 100\\% \\approx 12.90\\%\\) (ត្រូវនឹងមុំផ្ចិតប្រហែល \\(46.45^\\circ\\))</li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ចម្លើយ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div><p>ក្រុមហ៊ុនទទួលបានចំណូលពីការលក់ ៖ ទូរទស្សន៍ បាសនិងម៉ាញ៉េ ម៉ាស៊ីនព្រីន និងពីសេវាជួសជុលឧបករណ៍អេឡិចត្រូនិក ។ <br> ព័ត៌មាននេះមានសារៈប្រយោជន៍យ៉ាងសំខាន់សម្រាប់ការធ្វើផែនការហិរញ្ញវត្ថុ ៖</p><ul class=\"ts-bullets\"><li>ជួយកំណត់មុខទំនិញជាយុទ្ធសាស្ត្រ (ទូរទស្សន៍ និងបាស/ម៉ាញ៉េ រួមចំណែកជិត \\(68\\%\\) នៃចំណូលសរុប) ក្នុងការបែងចែកទុនបម្រុងទិញស្តុក</li></ul><ul class=\"ts-bullets\"><li>ជួយរៀបចំផែនការទីផ្សារដើម្បីជំរុញការលក់ម៉ាស៊ីនព្រីនដែលនៅមានចំណូលទាប</li></ul><ul class=\"ts-bullets\"><li>ជួយពង្រីកសេវាកម្មជួសជុលដើម្បីបង្កើតប្រភពចំណូលបន្ថែម</li></ul><ul class=\"ts-bullets\"><li>ជួយព្យាករចំណូលប្រចាំឆ្នាំ និងគ្រប់គ្រងលំហូរសាច់ប្រាក់ឱ្យមានស្ថិរភាព ។</li></ul><p>ដូចនេះ ក្រុមហ៊ុនរកចំណូលបានច្រើនជាងគេពីការលក់ទូរទស្សន៍ (\\(38.71\\%\\)) និងតិចជាងគេពីម៉ាស៊ីនព្រីន (\\(12.90\\%\\))។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ប្រតិបត្តិ 2</h2><p>ក្នុងកសិដ្ឋានមួយមានចិញ្ចឹមសត្វទាំងអស់ចំនួន 75 ក្បាល ក្នុងនោះមានគោ 15 ក្បាល ជ្រូក 28 ក្បាល ក្របី 10 ក្បាល និងទា 22 ក្បាល ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បង្កើតតារាងបំណែងចែកទិន្នន័យ</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>សង់ក្រាបផ្លិតតាងទិន្នន័យខាងលើ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ចម្លើយ <span class=\"ts-pg\">(១/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>គណនាមុំចម្រៀកថាស និងភាគរយតាងសត្វនីមួយៗ ៖ <br> ចំនួនសត្វសរុបគឺ \\(75\\) ក្បាល ត្រូវនឹងមុំផ្ចិត \\(360^\\circ\\) និង \\(100\\%\\)</p><ul class=\"ts-bullets\"><li>គោ ៖ មុំចម្រៀក \\(=\\frac{360^\\circ}{75}\\times15=72^\\circ\\), ភាគរយ \\(=\\frac{15}{75}\\times100\\%=20\\%\\)</li><li>ជ្រូក ៖ មុំចម្រៀក \\(=\\frac{360^\\circ}{75}\\times28=134.4^\\circ\\), ភាគរយ \\(=\\frac{28}{75}\\times100\\%\\approx37.33\\%\\)</li><li>ក្របី ៖ មុំចម្រៀក \\(=\\frac{360^\\circ}{75}\\times10=48^\\circ\\), ភាគរយ \\(=\\frac{10}{75}\\times100\\%\\approx13.33\\%\\)</li><li>ទា ៖ មុំចម្រៀក \\(=\\frac{360^\\circ}{75}\\times22=105.6^\\circ\\), ភាគរយ \\(=\\frac{22}{75}\\times100\\%\\approx29.33\\%\\)</li></ul><p>គេបានតារាងបំណែងចែកទិន្នន័យ ៖</p><table class=\"ts-table\"><tr><td>ប្រភេទសត្វ</td><td>ចំនួនសត្វ (ក្បាល)</td><td>ភាគរយ (%)</td><td>មុំចម្រៀកថាស</td></tr><tr><td>គោ</td><td>15</td><td>20%</td><td>\\(72^\\circ\\)</td></tr><tr><td>ជ្រូក</td><td>28</td><td>37.33%</td><td>\\(134.4^\\circ\\)</td></tr><tr><td>ក្របី</td><td>10</td><td>13.33%</td><td>\\(48^\\circ\\)</td></tr><tr><td>ទា</td><td>22</td><td>29.33%</td><td>\\(105.6^\\circ\\)</td></tr><tr><td>សរុប</td><td>75</td><td>100%</td><td>\\(360^\\circ\\)</td></tr></table></div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ក្រាបផ្លិតតាងទិន្នន័យខាងលើត្រូវបានបង្ហាញដូចរូបខាងលើ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">1. ក្រាបផ្លិត</p><h2>ចម្លើយ <span class=\"ts-pg\">(២/២)</span></h2><p>ដូចនេះ តារាងបំណែងចែកនិងក្រាបផ្លិតត្រូវបានបង្កើតពេញលេញដោយជ្រូកមានចំណែកធំជាងគេ (\\(134.4^\\circ\\)) និងក្របីតូចជាងគេ (\\(48^\\circ\\))។</p>"}, {"k": "title", "html": "<h1>2. ក្រាបខ្សែ</h1>"}, {"k": "", "html": "<p class=\"ts-kicker\"></p><h2>2. ក្រាបខ្សែ</h2><p><b>ក្រាបខ្សែ</b> ជាក្រាបដែលប្រើប្រាស់ខ្សែបន្ទាត់សម្រាប់ភ្ជាប់ពីចំណុចដៅមួយទៀត ដើម្បីបង្ហាញពីបម្រែបម្រួលទិន្នន័យក្នុងអំឡុងពេលជាក់លាក់ណាមួយ ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ក្រាបខ្សែ</p><h2>ឧទាហរណ៍ 1 <span class=\"ts-pg\">(១/២)</span></h2><p>តារាងខាងក្រោមបង្ហាញពីផែនការសន្សំរបស់បូរ៉ាក្នុងរយៈពេលមួយឆ្នាំ ។</p><table class=\"ts-table\"><tr><td>ខែ</td><td>មករា</td><td>កុម្ភៈ</td><td>មីនា</td><td>មេសា</td><td>ឧសភា</td><td>មិថុនា</td><td>កក្កដា</td><td>សីហា</td><td>កញ្ញា</td><td>តុលា</td><td>វិច្ឆិកា</td><td>ធ្នូ</td></tr><tr><td>ទឹកប្រាក់</td><td>20 000</td><td>10 000</td><td>15 000</td><td>25 000</td><td>30 000</td><td>8 000</td><td>22 000</td><td>28 000</td><td>30 000</td><td>40 000</td><td>36 000</td><td>6 000</td></tr></table><p>សង់ក្រាបខ្សែតាងទិន្នន័យខាងលើ</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ក្រាបខ្សែ</p><h2>ឧទាហរណ៍ 1 <span class=\"ts-pg\">(២/២)</span></h2><p>តាមរយៈក្រាបខ្សែនេះបង្ហាញថា ផែនការសន្សំរបស់បូរ៉ាមានការឡើងចុះដែលមិនស្ថិតនៅក្នុងចំនួនថេរឬប្រហាក់ប្រហែលគ្នាទេ។ យើងអាចសន្និដ្ឋានបានថា ផែនការសន្សំនេះប្រហែលជាប្រែប្រួលដោយសារស្ថានភាពនៃប្រាក់ចំណូលដែលគាត់ទទួលបាន និងការចំណាយប្រចាំខែរបស់គាត់ ។ ផែនការសន្សំជួយឱ្យអ្នកទុកដាក់ចំណូលមួយផ្នែកដោយទៀងទាត់សម្រាប់ប្រើប្រាស់នាពេលអនាគត ដែលជាយុទ្ធសាស្ត្រក្នុងការធ្វើផែនការហិរញ្ញវត្ថុ ដើម្បីសម្រេចបានគោលដៅ ។ ពេលខ្លះអ្នកមិនអាចដើរតាមផែនការបានទាំងស្រុងទេ ប៉ុន្តែការពិនិត្យតាមដានទៀងទាត់អាចជួយឱ្យអ្នកសម្រេចគោលដៅនេះបាន ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ក្រាបខ្សែ</p><h2>ឧទាហរណ៍ 2</h2><p>បកស្រាយក្រាបខ្សែខាងក្រោមដែលបង្ហាញពីផែនការចំណាយរយៈពេលមួយឆ្នាំរបស់បូរ៉ា ។</p><table class=\"ts-table\"><tr><td>ខែ</td><td>មករា</td><td>កុម្ភៈ</td><td>មីនា</td><td>មេសា</td><td>ឧសភា</td><td>មិថុនា</td><td>កក្កដា</td><td>សីហា</td><td>កញ្ញា</td><td>តុលា</td><td>វិច្ឆិកា</td><td>ធ្នូ</td></tr><tr><td>ចំណាយ</td><td>100 000</td><td>80 000</td><td>80 000</td><td>120 000</td><td>150 000</td><td>60 000</td><td>200 000</td><td>180 000</td><td>140 000</td><td>250 000</td><td>300 000</td><td>40 000</td></tr></table><p>ផ្អែកលើក្រាបខ្សែនេះ ផែនការចំណាយកើនឡើងគួរកត់សម្គាល់ចាប់ពីខែកក្កដា ហើយធ្លាក់ចុះបន្តិចនៅខែកញ្ញា ប៉ុន្តែនឹងកើនឡើងខ្ពស់បំផុតនៅខែវិច្ឆិកា ។ ដូច្នេះយើងអាចសន្និដ្ឋានថា ផែនការចំណាយពីមួយខែទៅមួយខែរបស់គាត់មិនស្មើគ្នាទេ ។ ផែនការចំណាយអាចឱ្យអ្នកព្យាករពីការចំណាយនាពេលអនាគតដែលមានប្រយោជន៍ក្នុងការធ្វើផែនការហិរញ្ញវត្ថុប្រចាំខែឬប្រចាំឆ្នាំរបស់បុគ្គល គ្រួសារ ឬស្ថាប័នមួយ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ក្រាបខ្សែ</p><h2>លំហាត់គំរូ 1</h2><p>ក្រាបខ្សែខាងក្រោមបង្ហាញពីផែនការហិរញ្ញវត្ថុប្រចាំឆ្នាំរបស់បូរ៉ា ។ តាមរយៈក្រាបខ្សែទាំងបី តើផែនការចំណាយនិងសន្សំរបស់គាត់ស្ថិតនៅក្នុងចំណូលរបស់គាត់ដែរឬទេ? តើផែនការសន្សំរបស់គាត់តិចបំផុតប៉ុន្មានរៀល បើធៀបនឹងចំណូលរបស់គាត់? ចូរពន្យល់ ។</p><table class=\"ts-table\"><tr><td>ខែ</td><td>មករា</td><td>កុម្ភៈ</td><td>មីនា</td><td>មេសា</td><td>ឧសភា</td><td>មិថុនា</td><td>កក្កដា</td><td>សីហា</td><td>កញ្ញា</td><td>តុលា</td><td>វិច្ឆិកា</td><td>ធ្នូ</td></tr><tr><td>ចំណូល</td><td>120 000</td><td>90 000</td><td>95 000</td><td>145 000</td><td>180 000</td><td>68 000</td><td>222 000</td><td>208 000</td><td>170 000</td><td>290 000</td><td>336 000</td><td>46 000</td></tr><tr><td>ចំណាយ</td><td>100 000</td><td>80 000</td><td>80 000</td><td>120 000</td><td>150 000</td><td>60 000</td><td>200 000</td><td>180 000</td><td>140 000</td><td>250 000</td><td>300 000</td><td>40 000</td></tr><tr><td>សន្សំ</td><td>20 000</td><td>10 000</td><td>15 000</td><td>25 000</td><td>30 000</td><td>8 000</td><td>22 000</td><td>28 000</td><td>30 000</td><td>40 000</td><td>36 000</td><td>6 000</td></tr></table>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ក្រាបខ្សែ</p><h2>ដំណោះស្រាយ</h2><p>តាមរយៈក្រាបខ្សែបង្ហាញពីផែនការហិរញ្ញវត្ថុប្រចាំឆ្នាំរបស់បូរ៉ា យើងអាចសន្និដ្ឋានបានថាផែនការចំណាយនិងសន្សំរបស់គាត់ស្ថិតនៅក្នុងរង្វង់ទឹកប្រាក់នៃចំណូលរបស់គាត់ ។ គាត់មានផែនការចំណាយនិងសន្សំប្រចាំខែច្បាស់លាស់ បើទោះបីខែខ្លះគាត់ទទួលបានចំណូលតិចក៏ដោយ ។ ផែនការសន្សំរបស់គាត់តិចបំផុត 6 000 ៛ ។ ជាមធ្យមផែនការសន្សំរបស់គាត់មានចំនួនប្រហែល 14% នៃចំណូលសរុបប្រចាំឆ្នាំ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ក្រាបខ្សែ</p><h2>ប្រតិបត្តិ 1</h2><p>ក្រាបខ្សែខាងក្រោមបង្ហាញពីផែនការសន្សំប្រចាំខែរបស់តារា ដើម្បីទិញកង់មួយតម្លៃ 235 000 ៛ ។</p><table class=\"ts-table\"><tr><td>ខែ</td><td>ខែទី១</td><td>ខែទី២</td><td>ខែទី៣</td><td>ខែទី៤</td><td>ខែទី៥</td></tr><tr><td>ទឹកប្រាក់សន្សំ</td><td>30 000</td><td>40 000</td><td>60 000</td><td>50 000</td><td>55 000</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ចូរបកស្រាយក្រាបខ្សែអំពីផែនការសន្សំប្រចាំខែរបស់តារា ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តាមរយៈផែនការសន្សំនេះ តើតារាអាចសម្រេចបានគោលដៅក្នុងរយៈពេល 5 ខែដែរឬទេ? ចូរពន្យល់ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ក្រាបខ្សែ</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>បកស្រាយក្រាបខ្សែអំពីការសន្សំរបស់តារា ៖</p><ul class=\"ts-bullets\"><li>ខែទី១ ៖ សន្សំបាន \\(30~000\\text{ ៛}\\)</li><li>ខែទី២ ៖ ការសន្សំកើនឡើងដល់ \\(40~000\\text{ ៛}\\) (កើន \\(10~000\\text{ ៛}\\))</li><li>ខែទី៣ ៖ ការសន្សំកើនឡើងដល់កម្រិតអតិបរមា គឺ \\(60~000\\text{ ៛}\\) (កើន \\(20~000\\text{ ៛}\\))</li><li>ខែទី៤ ៖ ការសន្សំថយចុះបន្តិចមកត្រឹម \\(50~000\\text{ ៛}\\) (ថយ \\(10~000\\text{ ៛}\\))</li><li>ខែទី៥ ៖ ការសន្សំកើនឡើងវិញដល់ \\(55~000\\text{ ៛}\\) (កើន \\(5~000\\text{ ៛}\\))</li></ul><p>ជារួម ផែនការសន្សំមានសន្ទុះកើនឡើងល្អ និងរក្សាបានយ៉ាងហោចណាស់ \\(30~000\\text{ ៛}\\) ក្នុងមួយខែ។</p></div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គណនាប្រាក់សន្សំសរុបក្នុងរយៈពេល 5 ខែ ៖ \\[\\begin{aligned}\n    S &amp;= 30~000 + 40~000 + 60~000 + 50~000 + 55~000 \\\\\n      &amp;= 235~000\\text{ ៛}\n    \\end{aligned}\\] តម្លៃកង់គឺ \\(235~000\\text{ ៛}\\) ស្មើគ្នានឹងប្រាក់សន្សំសរុប \\(S\\) ។ <br> ដូចនេះ តារាអាចសម្រេចគោលដៅទិញកង់ក្នុងរយៈពេល 5 ខែ ព្រោះប្រាក់សន្សំសរុបគ្រប់គ្រាន់ល្មម (\\(235~000\\text{ ៛}\\) លើ \\(235~000\\text{ ៛}\\))។</div></li></ul>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ២២</p><h1>លំហាត់</h1><p class=\"ts-sub\">ក្រាបផ្លិត និងក្រាបខ្សែ</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១</h2><p>ការបោះឆ្នោតជ្រើសរើសអ្នកដឹកនាំក្នុងទីក្រុងមួយ បង្ហាញលទ្ធផលដូចតារាងខាងក្រោម៖</p><table class=\"ts-table\"><tr><td>ឈ្មោះបេក្ខជន</td><td>A</td><td>B</td><td>C</td><td>D</td></tr><tr><td>ចំនួនសន្លឹកឆ្នោត</td><td>2045</td><td>4238</td><td>8605</td><td>12012</td></tr></table><p>តាងព័ត៌មានខាងលើដោយក្រាបផ្លិត ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១ <span class=\"ts-pg\">(១/២)</span></h2><p>គណនាចំនួនសន្លឹកឆ្នោតសរុប ៖ \\[\\begin{aligned}\nN &amp;= 2~045 + 4~238 + 8~605 + 12~012 \\\\\n  &amp;= 26~900\\text{ សន្លឹក}\n\\end{aligned}\\] សន្លឹកឆ្នោតសរុប \\(26~900\\) ត្រូវនឹងមុំផ្ចិត \\(360^\\circ\\) និង \\(100\\%\\) ។ <br> គណនាមុំចម្រៀកថាស និងភាគរយសម្រាប់បេក្ខជននីមួយៗ ៖</p><ul class=\"ts-bullets\"><li>បេក្ខជន A ៖ \\[\\begin{aligned}\n    \\theta_A &amp;= \\frac{360^\\circ}{26~900} \\times 2~045 \\approx 27.37^\\circ \\\\\n    p_A &amp;= \\frac{2~045}{26~900} \\times 100\\% \\approx 7.60\\%\n    \\end{aligned}\\]</li><li>បេក្ខជន B ៖ \\[\\begin{aligned}\n    \\theta_B &amp;= \\frac{360^\\circ}{26~900} \\times 4~238 \\approx 56.71^\\circ \\\\\n    p_B &amp;= \\frac{4~238}{26~900} \\times 100\\% \\approx 15.75\\%\n    \\end{aligned}\\]</li><li>បេក្ខជន C ៖ \\[\\begin{aligned}\n    \\theta_C &amp;= \\frac{360^\\circ}{26~900} \\times 8~605 \\approx 115.17^\\circ \\\\\n    p_C &amp;= \\frac{8~605}{26~900} \\times 100\\% \\approx 31.99\\%\n    \\end{aligned}\\]</li><li>បេក្ខជន D ៖ \\[\\begin{aligned}\n    \\theta_D &amp;= \\frac{360^\\circ}{26~900} \\times 12~012 \\approx 160.75^\\circ \\\\\n    p_D &amp;= \\frac{12~012}{26~900} \\times 100\\% \\approx 44.65\\%\n    \\end{aligned}\\]</li></ul><p>តារាងបំណែងចែកទិន្នន័យ ៖</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១ <span class=\"ts-pg\">(២/២)</span></h2><table class=\"ts-table\"><tr><td>បេក្ខជន</td><td>សន្លឹកឆ្នោត</td><td>ភាគរយ (%)</td><td>មុំចម្រៀកថាស</td></tr><tr><td>A</td><td>2 045</td><td>7.60%</td><td>\\(27.37^\\circ\\)</td></tr><tr><td>B</td><td>4 238</td><td>15.75%</td><td>\\(56.71^\\circ\\)</td></tr><tr><td>C</td><td>8 605</td><td>31.99%</td><td>\\(115.17^\\circ\\)</td></tr><tr><td>D</td><td>12 012</td><td>44.65%</td><td>\\(160.75^\\circ\\)</td></tr><tr><td>សរុប</td><td>26 900</td><td>100%</td><td>\\(360^\\circ\\)</td></tr></table><p>ផ្អែកលើមុំចម្រៀកថាសខាងលើ គេសង់បានក្រាបផ្លិតដូចរូបខាងលើ ។ <br> ដូចនេះ បេក្ខជន D ទទួលបានសន្លឹកឆ្នោតច្រើនជាងគេ (\\(44.65\\%\\), មុំ \\(160.75^\\circ\\)) ហើយបេក្ខជន A តិចជាងគេ (\\(7.60\\%\\), មុំ \\(27.37^\\circ\\))។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ២</h2><p>ក្រាបផ្លិតខាងស្តាំបង្ហាញពីដំណាំសំខាន់ៗ ដែលតំបន់មួយបានដាំលើដីចំនួន 450 ហិកតា ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>រកភាគរយនៃដីដំណាំនីមួយៗ</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រកផ្ទៃក្រឡាដីដំណាំនីមួយៗ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២ <span class=\"ts-pg\">(១/២)</span></h2><p>តាមក្រាបផ្លិតក្នុងសៀវភៅពុម្ព មុំចម្រៀកថាសនៃដំណាំទាំង \\(4\\) គឺ ៖ ស្រូវ \\(120^\\circ\\), សណ្ដែក \\(80^\\circ\\), ពោត \\(110^\\circ\\), និងល្ង \\(50^\\circ\\) (ផលបូកមុំ \\(120^\\circ + 80^\\circ + 110^\\circ + 50^\\circ = 360^\\circ\\)) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>គណនាភាគរយនៃដីដំណាំនីមួយៗធៀបនឹងផ្ទៃដីសរុប (មុំ \\(360^\\circ\\)) ៖</p><ul class=\"ts-bullets\"><li>ស្រូវ ៖ \\[p_{\\text{ស្រូវ}} = \\frac{120^\\circ}{360^\\circ} \\times 100\\% = \\frac{1}{3} \\times 100\\% \\approx 33.33\\%\\]</li></ul><ul class=\"ts-bullets\"><li>សណ្ដែក ៖ \\[p_{\\text{សណ្ដែក}} = \\frac{80^\\circ}{360^\\circ} \\times 100\\% = \\frac{2}{9} \\times 100\\% \\approx 22.22\\%\\]</li></ul><ul class=\"ts-bullets\"><li>ពោត ៖ \\[p_{\\text{ពោត}} = \\frac{110^\\circ}{360^\\circ} \\times 100\\% = \\frac{11}{36} \\times 100\\% \\approx 30.56\\%\\]</li></ul><ul class=\"ts-bullets\"><li>ល្ង ៖ \\[p_{\\text{ល្ង}} = \\frac{50^\\circ}{360^\\circ} \\times 100\\% = \\frac{5}{36} \\times 100\\% \\approx 13.89\\%\\]</li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div><p>គណនាផ្ទៃក្រឡាដីដំណាំនីមួយៗលើផ្ទៃដីសរុប \\(450\\text{ ហិកតា}\\) ៖</p><ul class=\"ts-bullets\"><li>ស្រូវ ៖ \\[S_{\\text{ស្រូវ}} = 450 \\times \\frac{120^\\circ}{360^\\circ} = 450 \\times \\frac{1}{3} = 150\\text{ ហិកតា}\\]</li></ul><ul class=\"ts-bullets\"><li>សណ្ដែក ៖ \\[S_{\\text{សណ្ដែក}} = 450 \\times \\frac{80^\\circ}{360^\\circ} = 450 \\times \\frac{2}{9} = 100\\text{ ហិកតា}\\]</li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li>ពោត ៖ \\[S_{\\text{ពោត}} = 450 \\times \\frac{110^\\circ}{360^\\circ} = 450 \\times \\frac{11}{36} = 137.5\\text{ ហិកតា}\\]</li></ul><ul class=\"ts-bullets\"><li>ល្ង ៖ \\[S_{\\text{ល្ង}} = 450 \\times \\frac{50^\\circ}{360^\\circ} = 450 \\times \\frac{5}{36} = 62.5\\text{ ហិកតា}\\]</li></ul><p>ដូចនេះ ផ្ទៃដីដាំស្រូវមាន \\(150\\text{ ហិកតា}\\) (\\(33.33\\%\\)) សណ្ដែក \\(100\\text{ ហិកតា}\\) (\\(22.22\\%\\)) ពោត \\(137.5\\text{ ហិកតា}\\) (\\(30.56\\%\\)) និងល្ង \\(62.5\\text{ ហិកតា}\\) (\\(13.89\\%\\))។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៣</h2><p>គេបែងចែកអ្នកទទួលបានប្រាក់ចំណូលប្រចាំថ្ងៃជា 4 ប្រភេទតាងដោយ A, B, C និង D ។ ក្រាបផ្លិតខាងស្តាំបង្ហាញពីចំនួនមនុស្សទទួលបានប្រាក់ចំណូលផ្សេងៗគ្នា ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាមុំនៃផ្នែក C</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គិតផ្នែកនីមួយៗជាភាគរយ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៣ <span class=\"ts-pg\">(១/២)</span></h2><p>តាមក្រាបផ្លិត មុំនៃផ្នែកនីមួយៗមាន \\(\\theta_A = 25^\\circ\\), \\(\\theta_B = 110^\\circ\\), \\(\\theta_D = 75^\\circ\\) ហើយមុំរង្វង់ទាំងមូលគឺ \\(360^\\circ\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាមុំនៃផ្នែក C ៖ \\[\\begin{aligned}\n    \\theta_C &amp;= 360^\\circ - (\\theta_A + \\theta_B + \\theta_D) \\\\\n             &amp;= 360^\\circ - (25^\\circ + 110^\\circ + 75^\\circ) \\\\\n             &amp;= 360^\\circ - 210^\\circ \\\\\n             &amp;= 150^\\circ\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div><p>គិតផ្នែកនីមួយៗជាភាគរយធៀបនឹងរង្វង់ទាំងមូល (\\(360^\\circ\\)) ៖</p><ul class=\"ts-bullets\"><li>ផ្នែក A ៖ \\[p_A = \\frac{25^\\circ}{360^\\circ} \\times 100\\% = \\frac{5}{72} \\times 100\\% \\approx 6.94\\%\\]</li><li>ផ្នែក B ៖ \\[p_B = \\frac{110^\\circ}{360^\\circ} \\times 100\\% = \\frac{11}{36} \\times 100\\% \\approx 30.56\\%\\]</li><li>ផ្នែក C ៖ \\[p_C = \\frac{150^\\circ}{360^\\circ} \\times 100\\% = \\frac{5}{12} \\times 100\\% \\approx 41.67\\%\\]</li><li>ផ្នែក D ៖ \\[p_D = \\frac{75^\\circ}{360^\\circ} \\times 100\\% = \\frac{5}{24} \\times 100\\% \\approx 20.83\\%\\]</li></ul><p>ផ្ទៀងផ្ទាត់ ៖ \\(6.94\\% + 30.56\\% + 41.67\\% + 20.83\\% = 100\\%\\) ។</p></div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៣ <span class=\"ts-pg\">(២/២)</span></h2><p>ដូចនេះ មុំនៃផ្នែក C គឺ \\(150^\\circ\\) ហើយភាគរយតាមផ្នែកគឺ \\(A \\approx 6.94\\%\\), \\(B \\approx 30.56\\%\\), \\(C \\approx 41.67\\%\\), \\(D \\approx 20.83\\%\\)។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៤</h2><p>គេធ្វើសម្ភាសន៍សិស្សចំនួន 30 នាក់ក្នុងថ្នាក់រៀនមួយពីចំណូលចិត្តផ្លែឈើ ហើយទទួលបានលទ្ធផលដូចក្នុងតារាងខាងក្រោម៖</p><table class=\"ts-table\"><tr><td>ឈ្មោះផ្លែឈើ</td><td>ក្រូច</td><td>ចេក</td><td>ស្វាយ</td><td>មៀន</td></tr><tr><td>ចំនួនសិស្ស</td><td>8</td><td>6</td><td>12</td><td>4</td></tr></table><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តាងទិន្នន័យជាក្រាបផ្លិត</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តាងទិន្នន័យជាក្រាបសសរ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤ <span class=\"ts-pg\">(១/៣)</span></h2><p>ចំនួនសិស្សសរុបគឺ \\(N = 8 + 6 + 12 + 4 = 30\\) នាក់ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤ <span class=\"ts-pg\">(២/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>តាងទិន្នន័យជាក្រាបផ្លិត ៖ <br> គណនាមុំចម្រៀកថាស និងភាគរយតាងផ្លែឈើនីមួយៗ ៖</p><ul class=\"ts-bullets\"><li>ក្រូច ៖ មុំ \\(=\\frac{360^\\circ}{30}\\times8=96^\\circ\\), ភាគរយ \\(=\\frac{8}{30}\\times100\\%\\approx26.67\\%\\)</li><li>ចេក ៖ មុំ \\(=\\frac{360^\\circ}{30}\\times6=72^\\circ\\), ភាគរយ \\(=\\frac{6}{30}\\times100\\%=20\\%\\)</li><li>ស្វាយ ៖ មុំ \\(=\\frac{360^\\circ}{30}\\times12=144^\\circ\\), ភាគរយ \\(=\\frac{12}{30}\\times100\\%=40\\%\\)</li><li>មៀន ៖ មុំ \\(=\\frac{360^\\circ}{30}\\times4=48^\\circ\\), ភាគរយ \\(=\\frac{4}{30}\\times100\\%\\approx13.33\\%\\)</li></ul><p>តារាងបំណែងចែកទិន្នន័យ ៖</p><table class=\"ts-table\"><tr><td>ឈ្មោះផ្លែឈើ</td><td>ចំនួនសិស្ស</td><td>ភាគរយ (%)</td><td>មុំចម្រៀកថាស</td></tr><tr><td>ក្រូច</td><td>8</td><td>26.67%</td><td>\\(96^\\circ\\)</td></tr><tr><td>ចេក</td><td>6</td><td>20.00%</td><td>\\(72^\\circ\\)</td></tr><tr><td>ស្វាយ</td><td>12</td><td>40.00%</td><td>\\(144^\\circ\\)</td></tr><tr><td>មៀន</td><td>4</td><td>13.33%</td><td>\\(48^\\circ\\)</td></tr><tr><td>សរុប</td><td>30</td><td>100%</td><td>\\(360^\\circ\\)</td></tr></table></div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តាងទិន្នន័យជាក្រាបសសរ ៖ <br> យកអ័ក្សដេកតាងប្រភេទផ្លែឈើ (ក្រូច, ចេក, ស្វាយ, មៀន) និងអ័ក្សឈរតាងចំនួនសិស្ស (ពី 0 ដល់ 14 នាក់)។ កម្ពស់សសរនីមួយៗស្មើនឹងចំនួនសិស្សរៀងគ្នាគឺ 8, 6, 12, និង 4 នាក់។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤ <span class=\"ts-pg\">(៣/៣)</span></h2><p>ក្រាបផ្លិតនិងក្រាបសសរត្រូវបានបង្ហាញដូចរូបខាងលើ ។ <br> ដូចនេះ ស្វាយត្រូវបានសិស្សចូលចិត្តច្រើនជាងគេ (\\(40\\%\\), មុំ \\(144^\\circ\\)) និងមៀនតិចជាងគេ (\\(13.33\\%\\), មុំ \\(48^\\circ\\))។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៥</h2><p>ក្រាបផ្លិតខាងស្តាំប្រាប់ពីប្រភេទសិស្សក្នុងថ្នាក់រៀនមួយ ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>រកមុំចម្រៀកថាសតាងសិស្សមធ្យម</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រកភាគរយនៃប្រភេទសិស្សនីមួយៗ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(១/២)</span></h2><p>តាមក្រាបផ្លិត មុំតាងសិស្សល្អគឺ \\(68^\\circ\\) និងមុំតាងសិស្សខ្សោយគឺ \\(81^\\circ\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាមុំចម្រៀកថាសតាងសិស្សមធ្យម ៖ <br> ដោយផលបូកមុំក្នុងរង្វង់ស្មើ \\(360^\\circ\\) គេបាន ៖ \\[\\begin{aligned}\n    \\theta_{\\text{មធ្យម}} &amp;= 360^\\circ - (\\theta_{\\text{ល្អ}} + \\theta_{\\text{ខ្សោយ}}) \\\\\n                          &amp;= 360^\\circ - (68^\\circ + 81^\\circ) \\\\\n                          &amp;= 360^\\circ - 149^\\circ \\\\\n                          &amp;= 211^\\circ\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div><p>គណនាភាគរយនៃប្រភេទសិស្សនីមួយៗ ៖</p><ul class=\"ts-bullets\"><li>សិស្សល្អ ៖ \\[p_{\\text{ល្អ}} = \\frac{68^\\circ}{360^\\circ} \\times 100\\% = \\frac{17}{90} \\times 100\\% \\approx 18.89\\%\\]</li><li>សិស្សខ្សោយ ៖ \\[p_{\\text{ខ្សោយ}} = \\frac{81^\\circ}{360^\\circ} \\times 100\\% = \\frac{9}{40} \\times 100\\% = 22.50\\%\\]</li><li>សិស្សមធ្យម ៖ \\[p_{\\text{មធ្យម}} = \\frac{211^\\circ}{360^\\circ} \\times 100\\% \\approx 58.61\\%\\]</li></ul><p>ផ្ទៀងផ្ទាត់ ៖ \\(18.89\\% + 22.50\\% + 58.61\\% = 100\\%\\) ។</p></div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(២/២)</span></h2><p>ដូចនេះ មុំចម្រៀកថាសតាងសិស្សមធ្យមគឺ \\(211^\\circ\\) ហើយភាគរយគឺ សិស្សល្អ \\(\\approx 18.89\\%\\), សិស្សខ្សោយ \\(= 22.50\\%\\), និងសិស្សមធ្យម \\(\\approx 58.61\\%\\)។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៦</h2><p>ក្នុងកសិដ្ឋានមួយគេចិញ្ចឹមសត្វ 120 ក្បាលដែលក្នុងនោះមានសត្វជ្រូក 35 ក្បាល សត្វគោ 20 ក្បាល សត្វមាន់ 53 ក្បាល និងសត្វទា 12 ក្បាល ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តាងទិន្នន័យជាក្រាបផ្លិត</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តាងទិន្នន័យជាក្រាបសសរ</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តើក្នុងកសិដ្ឋាននោះចិញ្ចឹមសត្វជ្រូក លើសសត្វគោប៉ុន្មានភាគរយ ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦ <span class=\"ts-pg\">(១/២)</span></h2><p>ចំនួនសត្វសរុបគឺ \\(N = 35 + 20 + 53 + 12 = 120\\) ក្បាល ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div><p>តាងទិន្នន័យជាក្រាបផ្លិត ៖ <br> គណនាមុំចម្រៀកថាស និងភាគរយតាងសត្វនីមួយៗ ៖</p><ul class=\"ts-bullets\"><li>ជ្រូក ៖ មុំ \\(=\\frac{360^\\circ}{120}\\times35=105^\\circ\\), ភាគរយ \\(=\\frac{35}{120}\\times100\\%\\approx29.17\\%\\)</li></ul><ul class=\"ts-bullets\"><li>គោ ៖ មុំ \\(=\\frac{360^\\circ}{120}\\times20=60^\\circ\\), ភាគរយ \\(=\\frac{20}{120}\\times100\\%\\approx16.67\\%\\)</li></ul><ul class=\"ts-bullets\"><li>មាន់ ៖ មុំ \\(=\\frac{360^\\circ}{120}\\times53=159^\\circ\\), ភាគរយ \\(=\\frac{53}{120}\\times100\\%\\approx44.17\\%\\)</li></ul><ul class=\"ts-bullets\"><li>ទា ៖ មុំ \\(=\\frac{360^\\circ}{120}\\times12=36^\\circ\\), ភាគរយ \\(=\\frac{12}{120}\\times100\\%=10\\%\\)</li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តាងទិន្នន័យជាក្រាបសសរ ៖ <br> យកអ័ក្សដេកតាងប្រភេទសត្វ (ជ្រូក, គោ, មាន់, ទា) និងអ័ក្សឈរតាងចំនួនសត្វ (ពី 0 ដល់ 60 ក្បាល)។ កម្ពស់សសរនីមួយៗស្មើនឹងចំនួនសត្វរៀងគ្នាគឺ 35, 20, 53, និង 12 ក្បាល។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div><p>គណនាភាគរយដែលសត្វជ្រូកលើសសត្វគោ ៖ <br> ចំនួនសត្វជ្រូកលើសសត្វគោគឺ \\(35 - 20 = 15\\) ក្បាល ។</p><ul class=\"ts-bullets\"><li><b>ករណីធៀបនឹងចំនួនសត្វសរុប (120 ក្បាល)</b> ៖ \\[\\Delta p_{\\text{សរុប}} = \\frac{35 - 20}{120} \\times 100\\% = \\frac{15}{120} \\times 100\\% = 12.5\\%\\] (ឬ \\(29.17\\% - 16.67\\% = 12.5\\%\\))</li></ul><ul class=\"ts-bullets\"><li><b>ករណីធៀបនឹងចំនួនសត្វគោ (20 ក្បាល)</b> ៖ \\[\\Delta p_{\\text{គោ}} = \\frac{35 - 20}{20} \\times 100\\% = \\frac{15}{20} \\times 100\\% = 75\\%\\]</li></ul><p>ក្រាបផ្លិតនិងក្រាបសសរត្រូវបានបង្ហាញដូចរូបខាងលើ ។ <br> ដូចនេះ មាន់មានចំនួនច្រើនជាងគេ (\\(44.17\\%\\)) ហើយជ្រូកលើសគោ \\(12.5\\%\\) នៃសត្វសរុប (ឬ \\(75\\%\\) ធៀបនឹងសត្វគោ)។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ២២</p><h1>ចប់មេរៀន</h1><p class=\"ts-sub\">ក្រាបផ្លិត និងក្រាបខ្សែ</p>"}];
